// The site's marketing pages (/, /platform, /about, /pricing and the eleven /features pages), from the v12 demo in
// pxispace-redesign/site-v12. pages/*.js and styles/*.css are generated by that demo's _build/port.py: change the demo,
// run the port, and commit what it writes. Only this file, V12Nav and V12Runtime are written by hand.
//
// The page's markup is server-rendered as the demo's HTML, so search engines read every word. The header is React
// (V12Nav), so it follows the real signed-in state. The demo's scripts then run once on that markup (V12Runtime).

import { preload } from 'react-dom';
import V12Nav from './V12Nav';
import V12Runtime from './V12Runtime';

// Before the first paint: html.v12-doc switches on the page's <html>/<body> rules (see styles/v12.css), and the page
// remembers it was loaded as a whole document (V12Runtime reloads when it was reached by a client-side navigation).
const DOC = "document.documentElement.classList.add('v12-doc');window.__v12doc=location.pathname;";

/** @param {{ page: { path: string, cur: string, html: string, inline: string[], jsonld: string[], fonts: string[], scripts: string[] } }} props */
export default function V12Page({ page }) {
  page.fonts.forEach((href) => preload(href, { as: 'font', type: 'font/woff2', crossOrigin: 'anonymous' }));
  return (
    <div className="v12">
      <script dangerouslySetInnerHTML={{ __html: DOC }} />
      {page.inline.map((code, i) => (
        <script key={`i${i}`} dangerouslySetInnerHTML={{ __html: code }} />
      ))}
      <V12Nav cur={page.cur} path={page.path} />
      <div className="v12-in" dangerouslySetInnerHTML={{ __html: page.html }} />
      {page.jsonld.map((json, i) => (
        <script key={`ld${i}`} type="application/ld+json" dangerouslySetInnerHTML={{ __html: json }} />
      ))}
      <V12Runtime scripts={page.scripts} />
    </div>
  );
}
